function bindCalendarSwipe(){var lane=root.querySelector('.cal-gridwrap');if(!lane)return;var drag=null;lane.addEventListener('pointerdown',function(e){if(e.pointerType==='mouse'&&e.button!==0)return;if(e.target.closest('input,textarea,select'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,dx:0,dy:0,axis:'',t:performance.now()};try{lane.setPointerCapture(e.pointerId)}catch(x){}},{passive:true});lane.addEventListener('pointermove',function(e){if(!drag||e.pointerId!==drag.id)return;drag.dx=e.clientX-drag.x;drag.dy=e.clientY-drag.y;if(!drag.axis&&(Math.abs(drag.dx)>4||Math.abs(drag.dy)>4))drag.axis=Math.abs(drag.dx)>Math.abs(drag.dy)*1.05?'x':'y';if(drag.axis==='x'&&e.cancelable)e.preventDefault()},{passive:false});function end(e){if(!drag||(e&&e.pointerId!==drag.id))return;var d=drag,ms=Math.max(1,performance.now()-d.t),v=Math.abs(d.dx)/ms;drag=null;try{lane.releasePointerCapture(d.id)}catch(x){}if(d.axis!=='x')return;if(Math.abs(d.dx)<28&&!(Math.abs(d.dx)>12&&v>.20))return;calendarSwipeBlockUntil=Date.now()+320;var step=d.dx<0?1:-1;S.cursor.setMonth(S.cursor.getMonth()+step);S.selected=key(new Date(S.cursor.getFullYear(),S.cursor.getMonth(),1,12));render();if(!checkout)refresh().catch(function(x){toast(x.message)})}lane.addEventListener('pointerup',end);lane.addEventListener('pointercancel',end);lane.addEventListener('lostpointercapture',end)}
