function rescheduleHub(){var upcoming=S.events.filter(function(e){return(e.kind==='fob_sesh'||e.kind==='lift_sesh')&&e.status==='scheduled'&&new Date(e.starts_at)>new Date()}).sort(function(a,b){return new Date(a.starts_at)-new Date(b.starts_at)});showSheet('<div class="cal-sheet-heading"><span class="cal-kicker">RESCHEDULE REQUEST</span><h2>Choose one session</h2><p class="sheet-copy">One session per request. Your current session stays authoritative while the request is reviewed.</p></div><div class="disclosure">If the original session OR your proposed new session is within 16 hours, you must accept a $12 late-reschedule fee before the request can be sent. The fee is only collected if the coach approves.</div><div class="cal-reschedule-list">'+(upcoming.length?upcoming.map(function(e){var r=activeRequestFor(e.id);return'<button '+(r&&r.status==='awaiting_payment'?'data-pay-request="'+h(r.id)+'"':'data-reschedule-event="'+h(e.id)+'"')+' '+(r&&r.status!=='awaiting_payment'?'disabled':'')+'><span><small>'+h(e.kind==='lift_sesh'?'LIFT SESH':'FOB SESH')+'</small><b>'+h(fmtDate(e.starts_at,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))+'</b></span>'+(r?'<em>'+h(r.status==='awaiting_payment'?'PAY $12':requestStateLabel(r))+'</em>':'<em>REQUEST</em>')+'</button>'}).join(''):'<div class="cal-empty-request">No upcoming training sessions are available to reschedule.</div>')+'</div><div class="sheet-actions is-centered"><button class="sheet-btn" data-sheet-close>Close</button></div>','cal-reschedule-hub')}
function updateLateFeeBox(){var sel=document.getElementById('requestStart'),box=document.getElementById('lateFeeBox'),check=document.getElementById('requestLateFee'),eventInput=document.getElementById('requestEvent');if(!sel||!box||!check||!eventInput)return;var e=S.events.find(function(x){return String(x.id)===String(eventInput.value)}),need=lateFeeNeeded(e,sel.value);box.hidden=!need;check.required=need;if(!need)check.checked=false}
function openRequest(eventId){var e=S.events.find(function(x){return String(x.id)===String(eventId)});if(!e)return;var existing=activeRequestFor(e.id);if(existing){toast('That session already has an open reschedule request.');return}var opts=S.availability.slots.filter(function(x){return new Date(x)>new Date()&&new Date(x).getTime()!==new Date(e.starts_at).getTime()&&!personalConflict(x)}).slice(0,400);showSheet('<div class="cal-sheet-heading"><span class="cal-kicker">RESCHEDULE // ONE SESSION</span><h2>Propose a new time</h2><p class="sheet-copy">Current: '+h(fmtDate(e.starts_at,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))+'</p></div><div class="disclosure">Your original session does not move when you submit this. If either the original session or the proposed time is within 16 hours, a $12 fee is required only if the coach approves; payment must be completed before the calendar can move.</div><form class="cal-form" id="requestForm"><input type="hidden" id="requestEvent" value="'+h(e.id)+'"><label>Requested opening<select id="requestStart" required><option value="">Choose an available time</option>'+opts.map(function(x){return'<option value="'+h(x)+'">'+h(fmtDate(x,{weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}))+'</option>'}).join('')+'</select></label><label>Reason<textarea id="requestReason" rows="3" placeholder="What changed?"></textarea></label><label class="cal-late-fee" id="lateFeeBox" hidden><input id="requestLateFee" type="checkbox"><span><b>I ACCEPT THE $12 LATE-RESCHEDULE CONDITION</b><small>This appears only when the original or proposed session is within 16 hours. No fee is collected unless the coach approves.</small></span></label><div class="sheet-actions is-centered"><button type="button" class="sheet-btn" data-sheet-close>Cancel</button><button class="sheet-btn is-primary" type="submit">Send request</button></div></form>','cal-request-sheet');updateLateFeeBox()}

function personalConflict(slot){var t=new Date(slot).getTime(),minutes=Number(S.availability.settings.sessionMinutes)||60,z=t+minutes*60000;return S.events.find(function(e){return e.kind==='personal'&&e.status==='scheduled'&&new Date(e.starts_at).getTime()<z&&new Date(e.ends_at).getTime()>t})}
function slotOverlap(a,b){var minutes=Number(S.availability.settings.sessionMinutes)||60,x=new Date(a).getTime(),y=new Date(b).getTime();return x<y+minutes*60000&&x+minutes*60000>y}
function selectionConflict(slot,list){return(list||S.selectedSlots).some(function(x){return new Date(x).getTime()!==new Date(slot).getTime()&&slotOverlap(x,slot)})}
function patternKey(slot){return fmtDate(slot,{weekday:'short'})+'|'+fmtDate(slot,{hour:'2-digit',minute:'2-digit',hour12:false})}
function rebuildRecurring(){var valid=S.availability.slots.filter(function(slot){return S.patterns.indexOf(patternKey(slot))>-1&&!personalConflict(slot)}).sort(function(a,b){return new Date(a)-new Date(b)}),chosen=[];valid.forEach(function(slot){if(chosen.length<S.pack&&!selectionConflict(slot,chosen))chosen.push(slot)});S.selectedSlots=chosen}
function openSlots(k){var slots=S.availability.slots.filter(function(x){return sameDay(x,k)}).sort(function(a,b){return new Date(a)-new Date(b)}),open=slots.filter(function(x){return!personalConflict(x)}),blocked=slots.filter(function(x){return!!personalConflict(x)});showSheet('<div class="cal-sheet-heading"><span class="cal-kicker">'+(S.recurring?'RECURRING SCHEDULE':'AVAILABLE TIMES')+'</span><h2>'+h(dateTitle(k))+'</h2><p class="sheet-copy">Only live openings are shown. Your personal events stay protected unless you explicitly remove one.</p></div><div class="slot-list">'+(open.map(function(slot){var on=S.selectedSlots.some(function(x){return new Date(x).getTime()===new Date(slot).getTime()}),over=!on&&selectionConflict(slot);return'<button class="slot'+(on?' is-on':'')+(over?' is-overlap':'')+'" data-slot="'+h(slot)+'"'+(over?' disabled aria-label="Overlaps another selected session"':'')+'>'+h(fmtTime(slot))+'</button>'}).join('')||'<p class="sheet-copy">No open times on this date.</p>')+'</div>'+(blocked.length?'<p class="cal-kicker slot-conflict-title">BLOCKED BY YOUR PERSONAL CALENDAR</p><div class="slot-list">'+blocked.map(function(slot){var conf=personalConflict(slot);return'<button class="slot is-conflict" data-slot="'+h(slot)+'" data-conflict="'+conf.id+'">'+h(fmtTime(slot))+'<small><br>'+h(conf.title)+'</small></button>'}).join('')+'</div>':'')+'<div class="sheet-actions is-centered"><button class="sheet-btn" data-sheet-close>Done</button></div>','cal-slot-sheet')}
function confirmConflict(eventId,slot){var e=S.events.find(function(x){return x.id===eventId});showSheet('<div class="cal-sheet-heading"><span class="cal-kicker">PERSONAL SCHEDULE CONFLICT</span><h2>Remove “'+h(e&&e.title||'this event')+'”?</h2><p class="sheet-copy">Removing it makes this time available for your FOB schedule.</p></div><div class="sheet-actions is-centered"><button class="sheet-btn" data-sheet-close>Keep it</button><button class="sheet-btn is-danger" data-resolve-conflict="'+h(eventId)+'" data-slot="'+h(slot)+'">Remove event</button></div>')}
function cursorBounds(){var from=new Date(S.cursor.getFullYear(),S.cursor.getMonth(),1,0),to=new Date(S.cursor.getFullYear(),S.cursor.getMonth()+2,8,0);from.setDate(from.getDate()-8);return{rangeFrom:from.toISOString(),rangeTo:to.toISOString()}}
